/**
 * Candidate A: `@apexdevtools/apex-parser`, a parser generated by ANTLR.
 *
 * The tree of the parser has one class per rule of the grammar. This file lowers it into the model of
 * `../syntax.ts`. It asks for the children of a node by their class and never trusts a typed accessor to return
 * something: after a syntax error the parser leaves nodes out.
 */
import type { TriggerUnitContext } from '@apexdevtools/apex-parser';
import {
  AnyIdContext,
  ApexErrorListener,
  ApexParserFactory,
  ArrayCreatorRestContext,
  ArrayExpressionContext,
  ArrayInitializerContext,
  ArraySubscriptsContext,
  AssignExpressionContext,
  BlockContext,
  BoundExpressionContext,
  CastExpressionContext,
  CatchClauseContext,
  ClassBodyContext,
  ClassBodyDeclarationContext,
  ClassCreatorRestContext,
  ClassDeclarationContext,
  CondExpressionContext,
  ConstructorDeclarationContext,
  CreatedNameContext,
  CreatorContext,
  DeleteStatementContext,
  DoWhileStatementContext,
  DotExpressionContext,
  DotMethodCallContext,
  ElseClauseContext,
  EnhancedForControlContext,
  EnumConstantsContext,
  EnumDeclarationContext,
  ExpressionContext,
  ExpressionListContext,
  ExpressionStatementContext,
  FieldDeclarationContext,
  FieldListContext,
  FieldNameContext,
  FieldNameListContext,
  FieldSpecContext,
  FinallyBlockContext,
  ForControlContext,
  ForInitContext,
  ForStatementContext,
  ForUpdateContext,
  FormalParameterContext,
  FormalParametersContext,
  FormalParameterListContext,
  FromNameListContext,
  GetterContext,
  IdContext,
  IdCreatedNamePairContext,
  IdPrimaryContext,
  IfStatementContext,
  InsertStatementContext,
  InstanceOfExpressionContext,
  InterfaceBodyContext,
  InterfaceDeclarationContext,
  InterfaceMethodDeclarationContext,
  LiteralContext,
  LiteralPrimaryContext,
  LocalVariableDeclarationContext,
  LocalVariableDeclarationStatementContext,
  MapCreatorRestContext,
  MapCreatorRestPairContext,
  MemberDeclarationContext,
  MergeStatementContext,
  MethodCallContext,
  MethodCallExpressionContext,
  MethodDeclarationContext,
  ModifierContext,
  NegExpressionContext,
  NewExpressionContext,
  ParExpressionContext,
  PostOpExpressionContext,
  PreOpExpressionContext,
  PrimaryExpressionContext,
  PropertyBlockContext,
  PropertyDeclarationContext,
  QualifiedNameContext,
  QueryContext,
  ReturnStatementContext,
  RunAsStatementContext,
  SelectEntryContext,
  SetCreatorRestContext,
  SetterContext,
  SoqlIdContext,
  SoqlLiteralContext,
  SoqlPrimaryContext,
  SoslIdContext,
  SoslLiteralAltContext,
  SoslLiteralContext,
  SoslPrimaryContext,
  StatementContext,
  SubExpressionContext,
  SubFieldEntryContext,
  SubQueryContext,
  SuperPrimaryContext,
  SwitchStatementContext,
  ThisPrimaryContext,
  ThrowStatementContext,
  TriggerBlockMemberContext,
  TriggerMemberDeclarationContext,
  TryStatementContext,
  TypeArgumentsContext,
  TypeDeclarationContext,
  TypeListContext,
  TypeNameContext,
  TypeOfContext,
  TypeRefContext,
  TypeRefPrimaryContext,
  UndeleteStatementContext,
  UpdateStatementContext,
  UpsertStatementContext,
  VariableDeclaratorContext,
  VariableDeclaratorsContext,
  WhenClauseContext,
  WhenControlContext,
  WhenValueContext,
  WhileStatementContext,
  type ApexParseTree,
  type ApexParserRuleContext,
  type ApexTerminalNode,
} from '@apexdevtools/apex-parser';
import type {
  Declarator,
  DmlOp,
  Expr,
  FieldPath,
  Member,
  Name,
  Param,
  Pos,
  Problem,
  Query,
  Search,
  Stmt,
  SyntaxAdapter,
  TriggerDecl,
  TypeDecl,
  TypeOf,
  TypeRef,
  Unit,
  When,
} from '../syntax.ts';

type Tree = ApexParseTree;
type Ctx = ApexParserRuleContext;
type CtxClass<T extends Ctx> = abstract new (...args: never[]) => T;

class Problems extends ApexErrorListener {
  readonly found: Problem[] = [];
  override apexSyntaxError(line: number, column: number, message: string): void {
    this.found.push({ at: { line, column: column + 1 }, message });
  }
}

const isTerminal = (node: Tree): node is ApexTerminalNode => (node as { symbol?: unknown }).symbol !== undefined;
const kids = (node: Tree | undefined): readonly Tree[] =>
  node === undefined || isTerminal(node) ? [] : ((node as Ctx).children ?? []);
const terminals = (node: Tree | undefined): ApexTerminalNode[] => kids(node).filter(isTerminal);
const all = <T extends Ctx>(node: Tree | undefined, type: CtxClass<T>): T[] =>
  kids(node).filter((kid): kid is T => kid instanceof type);
const one = <T extends Ctx>(node: Tree | undefined, type: CtxClass<T>): T | undefined => all(node, type)[0];
/** The text of the terminals that stand directly in a node, in lower case. */
const words = (node: Tree | undefined): string[] => terminals(node).map((token) => token.symbol.text.toLowerCase());

const START: Pos = { line: 1, column: 1 };
const posOf = (token: ApexTerminalNode): Pos => ({ line: token.symbol.line, column: token.symbol.column + 1 });
/** The place of the first token of a node. */
function startOf(node: Tree | undefined): Pos {
  if (node === undefined) return START;
  if (isTerminal(node)) return posOf(node);
  // A node that the parser made up after an error has no children and no start token of its own.
  const start = (node as { start?: { line: number; column: number } | null }).start;
  return start === undefined || start === null ? START : { line: start.line, column: start.column + 1 };
}
/** The one word a node such as `Id` or `AnyId` stands for. */
function nameOf(node: Tree | undefined): Name {
  const token = terminals(node)[0];
  return token === undefined ? { text: '', at: startOf(node) } : { text: token.symbol.text, at: posOf(token) };
}

function typeRef(ctx: TypeRefContext | undefined): TypeRef {
  const names = all(ctx, TypeNameContext);
  const parts = names.map((name) => {
    const id = one(name, IdContext);
    // `List`, `Set` and `Map` are keywords of the grammar and stand in the type name as a token.
    return id === undefined ? (terminals(name)[0]?.symbol.text ?? '') : nameOf(id).text;
  });
  const args = all(one(one(names.at(-1), TypeArgumentsContext), TypeListContext), TypeRefContext).map(typeRef);
  const array = words(one(ctx, ArraySubscriptsContext)).filter((word) => word === '[').length;
  return { name: parts.join('.'), args, array, at: startOf(ctx) };
}

const simpleType = (name: string, at: Pos): TypeRef => ({ name, args: [], array: 0, at });

function expressions(node: Tree | undefined): Expr[] {
  return all(node, ExpressionContext).map(expression);
}

function literal(ctx: LiteralContext | undefined): Expr {
  const token = terminals(ctx)[0];
  if (token === undefined) return { kind: 'unknown', parts: [] };
  const text = token.symbol.text;
  if (text.startsWith("'") && text.endsWith("'") && text.length >= 2 && !text.startsWith("'''")) {
    return { kind: 'string', at: posOf(token), raw: text.slice(1, -1) };
  }
  return { kind: 'literal', at: posOf(token), text };
}

function creator(ctx: CreatorContext | undefined): Expr {
  const pairs = all(one(ctx, CreatedNameContext), IdCreatedNamePairContext);
  const name = pairs.map((pair) => nameOf(one(pair, AnyIdContext)).text).join('.');
  const args = all(one(pairs.at(-1), TypeListContext), TypeRefContext).map(typeRef);
  const at = startOf(pairs[0]);
  const type: TypeRef = { name, args, array: 0, at };
  const map = one(ctx, MapCreatorRestContext);
  if (map !== undefined) {
    const entries = all(map, MapCreatorRestPairContext).map((pair) => {
      const [key, value] = expressions(pair);
      return { key: key ?? UNKNOWN, value: value ?? UNKNOWN };
    });
    return { kind: 'collection', type, elements: [], pairs: entries };
  }
  const set = one(ctx, SetCreatorRestContext);
  if (set !== undefined) return { kind: 'collection', type, elements: expressions(set), pairs: [] };
  const array = one(ctx, ArrayCreatorRestContext);
  if (array !== undefined) {
    const elements = [...expressions(array), ...expressions(one(array, ArrayInitializerContext))];
    return { kind: 'collection', type: { ...type, array: 1 }, elements, pairs: [] };
  }
  const rest = one(ctx, ClassCreatorRestContext);
  return {
    kind: 'new',
    type,
    args: expressions(
      one(
        kids(rest).find((kid) => !isTerminal(kid)),
        ExpressionListContext,
      ),
    ),
  };
}

const UNKNOWN: Expr = { kind: 'unknown', parts: [] };

function expression(ctx: Tree | undefined): Expr {
  if (ctx === undefined) return UNKNOWN;
  if (ctx instanceof PrimaryExpressionContext) {
    const primary = kids(ctx).find((kid) => !isTerminal(kid));
    if (primary instanceof IdPrimaryContext) return { kind: 'name', name: nameOf(one(primary, IdContext)) };
    if (primary instanceof LiteralPrimaryContext) return literal(one(primary, LiteralContext));
    if (primary instanceof ThisPrimaryContext) return { kind: 'this' };
    if (primary instanceof SuperPrimaryContext) return { kind: 'super' };
    if (primary instanceof TypeRefPrimaryContext) return { kind: 'class', type: typeRef(one(primary, TypeRefContext)) };
    if (primary instanceof SoqlPrimaryContext) {
      return { kind: 'soql', query: query(one(one(primary, SoqlLiteralContext), QueryContext)) };
    }
    if (primary instanceof SoslPrimaryContext) return { kind: 'sosl', search: search(primary) };
    return UNKNOWN;
  }
  if (ctx instanceof DotExpressionContext) {
    const target = expression(one(ctx, ExpressionContext));
    const call = one(ctx, DotMethodCallContext);
    if (call !== undefined) {
      const args = expressions(one(call, ExpressionListContext));
      return { kind: 'call', target, name: nameOf(one(call, AnyIdContext)), args };
    }
    return { kind: 'dot', target, name: nameOf(one(ctx, AnyIdContext)), safe: words(ctx).includes('?.') };
  }
  if (ctx instanceof MethodCallExpressionContext) {
    const call = one(ctx, MethodCallContext);
    const id = one(call, IdContext);
    // `this(...)` and `super(...)` call a constructor. The keyword is the name.
    const name = id === undefined ? nameOf(call) : nameOf(id);
    return { kind: 'call', target: undefined, name, args: expressions(one(call, ExpressionListContext)) };
  }
  if (ctx instanceof NewExpressionContext) return creator(one(ctx, CreatorContext));
  if (ctx instanceof SubExpressionContext) return expression(one(ctx, ExpressionContext));
  if (ctx instanceof CastExpressionContext) {
    return { kind: 'cast', type: typeRef(one(ctx, TypeRefContext)), expr: expression(one(ctx, ExpressionContext)) };
  }
  if (ctx instanceof InstanceOfExpressionContext) {
    return {
      kind: 'instanceof',
      expr: expression(one(ctx, ExpressionContext)),
      type: typeRef(one(ctx, TypeRefContext)),
    };
  }
  if (ctx instanceof ArrayExpressionContext) {
    const [target, index] = expressions(ctx);
    return { kind: 'index', target: target ?? UNKNOWN, index: index ?? UNKNOWN };
  }
  const parts = expressions(ctx);
  const op = words(ctx).join('');
  if (ctx instanceof AssignExpressionContext) {
    return { kind: 'assign', op, left: parts[0] ?? UNKNOWN, right: parts[1] ?? UNKNOWN };
  }
  if (ctx instanceof CondExpressionContext) {
    return { kind: 'ternary', cond: parts[0] ?? UNKNOWN, then: parts[1] ?? UNKNOWN, else: parts[2] ?? UNKNOWN };
  }
  if (
    ctx instanceof PostOpExpressionContext ||
    ctx instanceof PreOpExpressionContext ||
    ctx instanceof NegExpressionContext
  ) {
    return { kind: 'unary', op, operand: parts[0] ?? UNKNOWN };
  }
  if (ctx instanceof ExpressionContext && parts.length === 2) {
    return { kind: 'binary', op, left: parts[0] ?? UNKNOWN, right: parts[1] ?? UNKNOWN };
  }
  return { kind: 'unknown', parts };
}

/** The names of a `FieldName`, of a `SoslId` or of a `QualifiedName`: the words between the dots. */
function path(node: Tree | undefined): FieldPath {
  const names: Name[] = [];
  const walk = (at: Tree): void => {
    if (at instanceof IdContext) names.push(nameOf(at));
    else for (const kid of kids(at)) walk(kid);
  };
  if (node !== undefined) walk(node);
  return names;
}

interface QueryParts {
  fields: FieldPath[];
  children: Query[];
  nested: Query[];
  typeOfs: TypeOf[];
  binds: Expr[];
}

/** Collects what a clause of a query names. A sub-query, a `TYPEOF` and a bound expression are not walked into. */
function collect(node: Tree, into: QueryParts): void {
  for (const kid of kids(node)) {
    if (kid instanceof FromNameListContext) continue;
    if (kid instanceof SubQueryContext) {
      const inSelect = node instanceof SelectEntryContext || node instanceof SubFieldEntryContext;
      (inSelect ? into.children : into.nested).push(query(kid));
    } else if (kid instanceof TypeOfContext) {
      into.typeOfs.push({
        relationship: path(one(kid, FieldNameContext)),
        whens: all(kid, WhenClauseContext).map((when) => ({
          object: path(one(when, FieldNameContext))[0] ?? { text: '', at: startOf(when) },
          fields: all(one(when, FieldNameListContext), FieldNameContext).map(path),
        })),
        otherwise: all(one(one(kid, ElseClauseContext), FieldNameListContext), FieldNameContext).map(path),
      });
    } else if (kid instanceof BoundExpressionContext) {
      into.binds.push(expression(one(kid, ExpressionContext)));
    } else if (kid instanceof FieldNameContext) {
      into.fields.push(path(kid));
    } else if (kid instanceof SoqlIdContext || kid instanceof SoslIdContext) {
      // An alias, the name of a scope or of a list view. Not a field.
    } else {
      collect(kid, into);
    }
  }
}

function query(ctx: QueryContext | SubQueryContext | undefined): Query {
  const parts: QueryParts = { fields: [], children: [], nested: [], typeOfs: [], binds: [] };
  if (ctx === undefined) return { from: [], alias: undefined, ...parts };
  const fromList = one(ctx, FromNameListContext);
  const alias = one(fromList, SoqlIdContext);
  collect(ctx, parts);
  return {
    from: path(one(fromList, FieldNameContext)),
    alias: alias === undefined ? undefined : nameOf(one(alias, IdContext)).text.toLowerCase(),
    ...parts,
  };
}

function search(primary: SoslPrimaryContext): Search {
  const literalCtx = one(primary, SoslLiteralContext) ?? one(primary, SoslLiteralAltContext);
  const binds: Expr[] = [];
  const returning: { object: Name; fields: FieldPath[] }[] = [];
  const walk = (node: Tree): void => {
    for (const kid of kids(node)) {
      if (kid instanceof BoundExpressionContext) {
        binds.push(expression(one(kid, ExpressionContext)));
      } else if (kid instanceof FieldSpecContext) {
        const object = path(one(kid, SoslIdContext))[0];
        const parts: QueryParts = { fields: [], children: [], nested: [], typeOfs: [], binds: [] };
        const listed = (list: FieldListContext): void => {
          for (const entry of kids(list)) {
            if (entry instanceof SoslIdContext) parts.fields.push(path(entry));
            else if (entry instanceof FieldListContext) listed(entry);
            else collect(entry, parts);
          }
        };
        for (const part of kids(kid)) {
          if (part instanceof FieldListContext) listed(part);
          else if (!(part instanceof SoslIdContext)) collect(part, parts);
        }
        // A clause of a returned object stands directly in the field spec, so its own node is looked at as well.
        binds.push(...parts.binds);
        if (object !== undefined) returning.push({ object, fields: parts.fields });
      } else {
        walk(kid);
      }
    }
  };
  if (literalCtx !== undefined) walk(literalCtx);
  return { returning, binds };
}

function declarators(ctx: VariableDeclaratorsContext | undefined): Declarator[] {
  return all(ctx, VariableDeclaratorContext).map((declarator) => {
    const init = one(declarator, ExpressionContext);
    return { name: nameOf(one(declarator, IdContext)), init: init === undefined ? undefined : expression(init) };
  });
}

function local(ctx: LocalVariableDeclarationContext | undefined): Stmt {
  return {
    kind: 'local',
    type: typeRef(one(ctx, TypeRefContext)),
    vars: declarators(one(ctx, VariableDeclaratorsContext)),
  };
}

function block(ctx: BlockContext | undefined): Stmt {
  return { kind: 'block', stmts: all(ctx, StatementContext).map(statement) };
}

const DML: readonly [CtxClass<Ctx>, DmlOp][] = [
  [InsertStatementContext, 'insert'],
  [UpdateStatementContext, 'update'],
  [DeleteStatementContext, 'delete'],
  [UndeleteStatementContext, 'undelete'],
  [UpsertStatementContext, 'upsert'],
  [MergeStatementContext, 'merge'],
];

function statement(wrapper: StatementContext | undefined): Stmt {
  const ctx = kids(wrapper).find((kid) => !isTerminal(kid));
  if (ctx instanceof BlockContext) return block(ctx);
  if (ctx instanceof LocalVariableDeclarationStatementContext) {
    return local(one(ctx, LocalVariableDeclarationContext));
  }
  if (ctx instanceof ExpressionStatementContext) return { kind: 'expr', expr: expression(one(ctx, ExpressionContext)) };
  if (ctx instanceof IfStatementContext) {
    const [then, otherwise] = all(ctx, StatementContext);
    return {
      kind: 'if',
      cond: expression(one(one(ctx, ParExpressionContext), ExpressionContext)),
      then: statement(then),
      else: otherwise === undefined ? undefined : statement(otherwise),
    };
  }
  if (ctx instanceof SwitchStatementContext) {
    const whens = all(ctx, WhenControlContext).map((when): When => {
      const value = one(when, WhenValueContext);
      const type = one(value, TypeRefContext);
      const binding = type === undefined ? undefined : { type: typeRef(type), name: nameOf(one(value, IdContext)) };
      return { binding, values: [], block: block(one(when, BlockContext)) };
    });
    return { kind: 'switch', on: expression(one(ctx, ExpressionContext)), whens };
  }
  if (ctx instanceof ForStatementContext) {
    const control = one(ctx, ForControlContext);
    const body = one(ctx, StatementContext);
    const each = one(control, EnhancedForControlContext);
    if (each !== undefined) {
      return {
        kind: 'foreach',
        type: typeRef(one(each, TypeRefContext)),
        name: nameOf(one(each, IdContext)),
        iterable: expression(one(each, ExpressionContext)),
        body: body === undefined ? undefined : statement(body),
      };
    }
    const init = one(control, ForInitContext);
    const declared = one(init, LocalVariableDeclarationContext);
    const cond = one(control, ExpressionContext);
    return {
      kind: 'for',
      init:
        declared === undefined
          ? expressions(one(init, ExpressionListContext)).map((expr): Stmt => ({ kind: 'expr', expr }))
          : [local(declared)],
      cond: cond === undefined ? undefined : expression(cond),
      update: expressions(one(one(control, ForUpdateContext), ExpressionListContext)),
      body: body === undefined ? undefined : statement(body),
    };
  }
  if (ctx instanceof WhileStatementContext || ctx instanceof DoWhileStatementContext) {
    const body = one(ctx, StatementContext);
    const doBody = one(ctx, BlockContext);
    return {
      kind: 'while',
      cond: expression(one(one(ctx, ParExpressionContext), ExpressionContext)),
      body: body === undefined ? (doBody === undefined ? undefined : block(doBody)) : statement(body),
    };
  }
  if (ctx instanceof TryStatementContext) {
    const last = one(one(ctx, FinallyBlockContext), BlockContext);
    return {
      kind: 'try',
      block: block(one(ctx, BlockContext)),
      catches: all(ctx, CatchClauseContext).map((clause) => {
        const type = path(one(clause, QualifiedNameContext));
        return {
          type: simpleType(type.map((name) => name.text).join('.'), type[0]?.at ?? startOf(clause)),
          name: nameOf(one(clause, IdContext)),
          block: block(one(clause, BlockContext)),
        };
      }),
      finally: last === undefined ? undefined : block(last),
    };
  }
  if (ctx instanceof ReturnStatementContext) {
    const value = one(ctx, ExpressionContext);
    return { kind: 'return', expr: value === undefined ? undefined : expression(value) };
  }
  if (ctx instanceof ThrowStatementContext) return { kind: 'throw', expr: expression(one(ctx, ExpressionContext)) };
  if (ctx instanceof RunAsStatementContext) {
    return { kind: 'runas', args: expressions(one(ctx, ExpressionListContext)), block: block(one(ctx, BlockContext)) };
  }
  for (const [type, op] of DML) {
    if (ctx instanceof type) {
      return {
        kind: 'dml',
        op,
        at: startOf(terminals(ctx)[0]),
        targets: expressions(ctx),
        key: path(one(ctx, QualifiedNameContext)),
      };
    }
  }
  return { kind: 'other' };
}

function parameters(ctx: FormalParametersContext | undefined): Param[] {
  return all(one(ctx, FormalParameterListContext), FormalParameterContext).map((parameter) => ({
    type: typeRef(one(parameter, TypeRefContext)),
    name: nameOf(one(parameter, IdContext)),
  }));
}

/** The modifiers of a declaration, in lower case. An annotation is not one. */
function modifiers(owner: Tree | undefined): Set<string> {
  return new Set(all(owner, ModifierContext).flatMap(words));
}

function member(
  declaration: MemberDeclarationContext | TriggerMemberDeclarationContext | undefined,
  marks: ReadonlySet<string>,
): Member | undefined {
  const ctx = kids(declaration).find((kid) => !isTerminal(kid));
  const isStatic = marks.has('static');
  if (ctx instanceof MethodDeclarationContext) {
    const returns = one(ctx, TypeRefContext);
    const body = one(ctx, BlockContext);
    return {
      kind: 'method',
      name: nameOf(one(ctx, IdContext)),
      ctor: false,
      static: isStatic,
      params: parameters(one(ctx, FormalParametersContext)),
      returns: returns === undefined ? undefined : typeRef(returns),
      body: body === undefined ? undefined : block(body),
    };
  }
  if (ctx instanceof ConstructorDeclarationContext) {
    const name = path(one(ctx, QualifiedNameContext)).at(-1);
    return {
      kind: 'method',
      name: name ?? { text: '', at: startOf(ctx) },
      ctor: true,
      static: false,
      params: parameters(one(ctx, FormalParametersContext)),
      returns: undefined,
      body: block(one(ctx, BlockContext)),
    };
  }
  if (ctx instanceof FieldDeclarationContext) {
    return {
      kind: 'field',
      type: typeRef(one(ctx, TypeRefContext)),
      static: isStatic,
      final: marks.has('final'),
      vars: declarators(one(ctx, VariableDeclaratorsContext)),
    };
  }
  if (ctx instanceof PropertyDeclarationContext) {
    const accessors = all(ctx, PropertyBlockContext).flatMap((accessor) => {
      const body = one(one(accessor, GetterContext) ?? one(accessor, SetterContext), BlockContext);
      return body === undefined ? [] : [block(body)];
    });
    return {
      kind: 'property',
      type: typeRef(one(ctx, TypeRefContext)),
      static: isStatic,
      name: nameOf(one(ctx, IdContext)),
      accessors,
    };
  }
  const decl = typeDeclaration(ctx);
  return decl === undefined ? undefined : { kind: 'type', decl };
}

function typeDeclaration(ctx: Tree | undefined): TypeDecl | undefined {
  if (ctx instanceof ClassDeclarationContext) {
    const base = one(ctx, TypeRefContext);
    const members: Member[] = [];
    for (const declaration of all(one(ctx, ClassBodyContext), ClassBodyDeclarationContext)) {
      const body = one(declaration, BlockContext);
      if (body !== undefined) {
        members.push({ kind: 'initializer', static: words(declaration).includes('static'), body: block(body) });
        continue;
      }
      const found = member(one(declaration, MemberDeclarationContext), modifiers(declaration));
      if (found !== undefined) members.push(found);
    }
    return {
      kind: 'class',
      name: nameOf(one(ctx, IdContext)),
      extends: base === undefined ? undefined : typeRef(base),
      members,
      values: [],
    };
  }
  if (ctx instanceof InterfaceDeclarationContext) {
    const members = all(one(ctx, InterfaceBodyContext), InterfaceMethodDeclarationContext).map((method): Member => {
      const returns = one(method, TypeRefContext);
      return {
        kind: 'method',
        name: nameOf(one(method, IdContext)),
        ctor: false,
        static: false,
        params: parameters(one(method, FormalParametersContext)),
        returns: returns === undefined ? undefined : typeRef(returns),
        body: undefined,
      };
    });
    return { kind: 'interface', name: nameOf(one(ctx, IdContext)), extends: undefined, members, values: [] };
  }
  if (ctx instanceof EnumDeclarationContext) {
    const values = all(one(ctx, EnumConstantsContext), IdContext).map(nameOf);
    return { kind: 'enum', name: nameOf(one(ctx, IdContext)), extends: undefined, members: [], values };
  }
  return undefined;
}

function trigger(ctx: TriggerUnitContext): TriggerDecl {
  const [name, object] = all(ctx, IdContext);
  const body: Stmt[] = [];
  const members: Member[] = [];
  for (const block of kids(ctx).filter((kid) => !isTerminal(kid))) {
    for (const entry of all(block, TriggerBlockMemberContext)) {
      const stmt = one(entry, StatementContext);
      if (stmt !== undefined) body.push(statement(stmt));
      const declaration = one(entry, TriggerMemberDeclarationContext);
      const variable = one(declaration, FieldDeclarationContext);
      if (variable !== undefined) {
        // The grammar reads a variable of the body of a trigger as a field. It is a local: the statements after
        // it see it, and it has no key of its own.
        body.push({
          kind: 'local',
          type: typeRef(one(variable, TypeRefContext)),
          vars: declarators(one(variable, VariableDeclaratorsContext)),
        });
        continue;
      }
      const found = member(declaration, modifiers(entry));
      if (found !== undefined) members.push(found);
    }
  }
  return { name: nameOf(name), object: nameOf(object), body, members };
}

export function createApexParserAdapter(): SyntaxAdapter {
  return {
    name: 'apex-parser',
    parseUnit(source, kind): Unit {
      const problems = new Problems();
      try {
        const { parser } = ApexParserFactory.createLexerAndParser(source, problems);
        if (kind === 'trigger') {
          return { types: [], trigger: trigger(parser.triggerUnit()), problems: problems.found };
        }
        const unit = parser.compilationUnit();
        const types = all(unit, TypeDeclarationContext).flatMap((declaration) => {
          const decl = typeDeclaration(
            kids(declaration).find((kid) => !isTerminal(kid) && !(kid instanceof ModifierContext)),
          );
          return decl === undefined ? [] : [decl];
        });
        return { types, trigger: undefined, problems: problems.found };
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        return { types: [], trigger: undefined, problems: [...problems.found, { at: START, message }] };
      }
    },
    parseQuery(text): Query | undefined {
      const problems = new Problems();
      try {
        const { parser } = ApexParserFactory.createLexerAndParser(text, problems);
        const tree = parser.query();
        // The rule stops where the query stops. Text after it means that this was not one query.
        if (problems.found.length > 0 || parser.getCurrentToken().type !== -1) return undefined;
        return query(tree);
      } catch {
        return undefined;
      }
    },
  };
}
